+    fn handle_visual_key(
+        &mut self,
+        key: UiKey,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) -> Vec<UiAction> {
+        match key {
+            UiKey::Esc => {
+                self.visual_selection = None;
+                self.mode = UiMode::Command;
+            }
+            UiKey::Char('v') => {
+                self.change_visual_kind(
+                    VisualKind::Character,
+                    right_content,
+                    right_cursor_column,
+                );
+            }
+            UiKey::Char('V') => {
+                self.change_visual_kind(VisualKind::Line, right_content, right_cursor_column);
+            }
+            UiKey::Char('\u{16}') => {
+                self.change_visual_kind(VisualKind::Block, right_content, right_cursor_column);
+            }
+            UiKey::Char('h') | UiKey::Left => {
+                self.move_visual_cursor(0, -1, right_content);
+            }
+            UiKey::Char('l') | UiKey::Right => {
+                self.move_visual_cursor(0, 1, right_content);
+            }
+            UiKey::Char('j') | UiKey::Down => {
+                self.move_visual_cursor(1, 0, right_content);
+            }
+            UiKey::Char('k') | UiKey::Up => {
+                self.move_visual_cursor(-1, 0, right_content);
+            }
+            UiKey::Char('y') => {
+                self.yank_visual_selection(false, right_content);
+            }
+            UiKey::Char('Y') => {
+                self.yank_visual_selection(true, right_content);
+            }
+            _ => {}
+        }
+        Vec::new()
+    }
+
+    fn start_visual_selection(
+        &mut self,
+        kind: VisualKind,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) {
+        let cursor = self.visual_start_point(kind, right_content, right_cursor_column);
+        self.visual_selection = Some(VisualSelection {
+            pane: self.focus,
+            kind,
+            anchor: cursor,
+            cursor,
+        });
+        self.mode = UiMode::Command;
+    }
+
+    fn change_visual_kind(
+        &mut self,
+        kind: VisualKind,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) {
+        if let Some(selection) = &mut self.visual_selection {
+            selection.kind = kind;
+        } else {
+            self.start_visual_selection(kind, right_content, right_cursor_column);
+        }
+    }
+
+    fn visual_start_point(
+        &self,
+        kind: VisualKind,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) -> TextPoint {
+        match self.focus {
+            PaneFocus::Left => TextPoint {
+                line: self.control_selected_line_index(),
+                column: 0,
+            },
+            PaneFocus::Right => {
+                let lines = self.right_visual_lines(right_content);
+                let line = lines.len().saturating_sub(1);
+                let line_width = char_count(&lines[line]);
+                let column = if kind == VisualKind::Line {
+                    0
+                } else {
+                    right_cursor_column
+                        .unwrap_or(line_width)
+                        .saturating_sub(1)
+                        .min(line_width.saturating_sub(1))
+                };
+                TextPoint { line, column }
+            }
+        }
+    }
+
+    fn move_visual_cursor(&mut self, line_delta: isize, column_delta: isize, right_content: &str) {
+        let Some(current) = self.visual_selection.clone() else {
+            return;
+        };
+        let lines = self.selection_lines(current.pane, right_content);
+        let last_line = lines.len().saturating_sub(1);
+        let line = current
+            .cursor
+            .line
+            .saturating_add_signed(line_delta)
+            .min(last_line);
+        let max_column = char_count(&lines[line]).saturating_sub(1);
+        let column = current
+            .cursor
+            .column
+            .saturating_add_signed(column_delta)
+            .min(max_column);
+        if let Some(selection) = &mut self.visual_selection {
+            selection.cursor = TextPoint { line, column };
+        }
+    }
+
+    fn yank_visual_selection(&mut self, force_linewise: bool, right_content: &str) {
+        let Some(mut selection) = self.visual_selection.clone() else {
+            return;
+        };
+        if force_linewise {
+            selection.kind = VisualKind::Line;
+        }
+        let lines = self.selection_lines(selection.pane, right_content);
+        let yanked = selected_text(&selection, &lines);
+        let char_count = yanked.chars().count();
+        self.last_yank = Some(yanked);
+        self.visual_selection = None;
+        self.show_status_notice(
+            format!("yanked {char_count} chars"),
+            Duration::from_secs(STATUS_NOTICE_SECONDS),
+        );
+    }
+
+    fn selection_lines(&self, pane: PaneFocus, right_content: &str) -> Vec<String> {
+        match pane {
+            PaneFocus::Left => {
+                let inner_width =
+                    usize::from(self.layout().left_width.saturating_sub(2).max(1));
+                self.left_pane_rows(inner_width)
+                    .into_iter()
+                    .map(|row| row.text)
+                    .collect()
+            }
+            PaneFocus::Right => self.right_visual_lines(right_content),
+        }
+    }
+
+    fn right_visual_lines(&self, right_content: &str) -> Vec<String> {
+        text_lines(&self.visible_right_content(right_content))
+    }
+
+    fn left_pane_rows(&self, inner_width: usize) -> Vec<LeftPaneRow> {
+        let mut rows = vec![LeftPaneRow {
+            text: if self.control_selected == 0 {
+                "> work-leaf  command".to_string()
+            } else {
+                "  work-leaf  command".to_string()
+            },
+            ready: false,
+        }];
+        for (visible_position, agent_index) in self.visible_agent_indices().iter().enumerate() {
+            let agent = &self.agents[*agent_index];
+            let selected = self.control_selected == visible_position + 1;
+            rows.push(LeftPaneRow {
+                text: compact_agent_row(agent, selected, inner_width),
+                ready: agent.ready,
+            });
+            if !agent.modified_files.is_empty() {
+                rows.push(LeftPaneRow {
+                    text: format!(
+                        "    files: {}",
+                        agent
+                            .modified_files
+                            .iter()
+                            .map(|path| path.display().to_string())
+                            .collect::<Vec<_>>()
+                            .join(", ")
+                    ),
+                    ready: false,
+                });
+            }
+            for (label, agents) in [
+                ("conflicts", &agent.conflicting_agents),
+                ("depends-on", &agent.depends_on),
+                ("depended-on-by", &agent.depended_on_by),
+            ] {
+                if !agents.is_empty() {
+                    rows.push(LeftPaneRow {
+                        text: format!(
+                            "    {label}: {}",
+                            agents
+                                .iter()
+                                .map(AgentId::as_str)
+                                .collect::<Vec<_>>()
+                                .join(", ")
+                        ),
+                        ready: false,
+                    });
+                }
+            }
+        }
+        rows
+    }
+
+    fn control_selected_line_index(&self) -> usize {
+        if self.control_selected == 0 {
+            return 0;
+        }
+        let mut line = 1;
+        for (visible_position, agent_index) in self.visible_agent_indices().iter().enumerate() {
+            if self.control_selected == visible_position + 1 {
+                return line;
+            }
+            line += 1;
+            let agent = &self.agents[*agent_index];
+            if !agent.modified_files.is_empty() {
+                line += 1;
+            }
+            for linked_agents in [
+                &agent.conflicting_agents,
+                &agent.depends_on,
+                &agent.depended_on_by,
+            ] {
+                if !linked_agents.is_empty() {
+                    line += 1;
+                }
+            }
+        }
+        0
+    }
+
+    fn selection_spans(
+        &self,
+        pane: PaneFocus,
+        line_index: usize,
+        line: &str,
+    ) -> Spans<'static> {
+        let Some((start, end)) = self.selection_range_for_line(pane, line_index, line) else {
+            return Spans::from(vec![Span::raw(line.to_string())]);
+        };
+        if start == end {
+            return Spans::from(vec![Span::raw(line.to_string())]);
+        }
+        let chars = line.chars().collect::<Vec<_>>();
+        let before = chars[..start].iter().collect::<String>();
+        let selected = chars[start..end].iter().collect::<String>();
+        let after = chars[end..].iter().collect::<String>();
+        Spans::from(vec![
+            Span::raw(before),
+            Span::styled(selected, Style::default().add_modifier(Modifier::REVERSED)),
+            Span::raw(after),
+        ])
+    }
+
+    fn selection_range_for_line(
+        &self,
+        pane: PaneFocus,
+        line_index: usize,
+        line: &str,
+    ) -> Option<(usize, usize)> {
+        let selection = self
+            .visual_selection
+            .as_ref()
+            .filter(|selection| selection.pane == pane)?;
+        selected_range_for_line(selection, line_index, char_count(line))
+    }
